    "name_en": "George Town Shophouses & Five-Foot Way",
    "name_local": "Five-foot way / Kaki lima",
    "name_local_roman": "—",
    "tradition": "海峡华人、英殖民与闽南混血建筑传统",
    "summary": "槟城乔治市的骑楼群形成于19世纪至20世纪初，是海峡华人工商业繁荣时期的产物。建筑通常为两至三层联排窄面宽，底层后退形成连续的有顶走廊'五脚基'（Kaki Lima），为行人遮阳挡雨，也是小贩营生与街坊邻里社交的公共灰空间。建筑立面融合闽南灰塑山花、南洋百叶木窗、殖民风格爱奥尼壁柱与华丽的英式/欧洲釉面花砖，2008年作为世界文化遗产核心要素被联合国教科文组织收录。",
    "visual_features": {
      "form": "双坡屋顶，联排窄开间（面宽约4-5米）、进深极深（可达30-50米，内设采光天井），底层后退连续柱廊构成五脚基拱廊通道。",
      "color": "粉彩调色板为主，湖水绿、鹅黄、天蓝、靛青与白色石灰水涂层相间，色彩斑斓且与热带强光形成柔和对比。",
      "material": "红砖砌筑、抹灰浮雕山花、柚木或菠萝格百叶窗扇、锻铁防盗栏杆、水磨石及彩色水泥釉面印花地砖。",
      "pattern": "山花中央常饰中式吉祥堂号或西式卷草花环纹，腰墙镶嵌马约利卡风格花砖（Majolica tiles）呈对称几何花草图案。",
      "space": "连续通廊进深约1.5米（约5英尺），层高约3.2-3.8米，虚实相间，提供深邃的纵深透视与街道空间阴影界面。",
      "distinction": "相比马六甲早期低矮厚重的荷兰红砖式店屋，槟城骑楼更为修长挺拔，立面装饰中西合璧的海峡折衷主义（Straits Eclectic）特征更为繁复华丽。"
    },
