    "name_cn": "金马仑高原阶梯茶园台地景观",
    "name_en": "Cameron Highlands Terraced Tea Plantations",
    "name_local": "Tanah Tinggi Cameron",
    "name_local_roman": "—",
    "tradition": "英殖民避暑高原开发、南亚与华工茶叶种植台地农耕地景",
    "summary": "金马仑高原位于马来西亚蒂蒂旺沙山脉海拔约1500米的高处，自20世纪初被英国农业学者发现并开辟为殖民时期避暑胜地与茶园基地（如著名的 BOH 与 Bharat 茶园）。连绵数十个山头的茶树依山势修剪成波浪起伏的等高线阶梯台地，晨雾笼罩其间，茶树修剪成平整的弧形球冠状，构成柔美如丝绒般的大地肌理。这一景观既是热带高山微气候与近代人工种植智慧的结合，也是当代逃离热带炎暑的经典视觉田园意象。",
    "visual_features": {
      "form": "随山体起伏而顺势延展的环形等高线水平阶梯，茶树行修剪成平滑连续的绿色波纹带与弧形曲面。",
      "color": "嫩草绿新芽与墨绿老叶交织，泥土红褐色巡山小径，雨后清晨弥漫青白色的高山晨雾。",
      "material": "密植常绿茶树冠层灌木、红壤阶地梯道、高山冷凉山雾水汽与殖民风格铁皮茶厂建筑。",
      "pattern": "大地指纹般的等高线曲线环状纹样、台阶层层叠落的明暗阴影韵律节奏。",
      "space": "俯瞰时具有强烈的空间纵深与开阔全景包容感，步道穿插其间形成极具探索趣味的起伏漫游动线。",
      "distinction": "比中国江南平缓茶园或斯里兰卡高山茶园更为连绵紧凑，热带高日照下茶丛油绿光洁，与周围野生雨林林缘线形成鲜明的几何与有机对比。"
    },
