    "name_cn": "槟城炭火铁镬炒粿条与芭蕉叶街头排档",
    "name_en": "Penang Charcoal Wok Char Kway Teow Stall",
    "name_local": "炒粿條 / Char koay teow",
    "name_local_roman": "Char kway teow",
    "tradition": "潮州移民饮食演变、南洋小贩铁镬镬气（Wok Hei）烹饪文化",
    "summary": "炒粿条是槟城街头美食皇冠上的明珠，源自早期潮州渔民与码头劳工的高热量快炒食物。传统正宗摊档坚持使用传统圆底生铁大镬（Cast iron wok）架设于通红的红木炭火炉（或猛火喷火炉）之上。小贩头戴护目镜或汗巾，手持铁铲与长筷，以极高油温在数十秒内飞速翻炒扁平米粉粿条、海虾、鲜蛤、豆芽、韭菜与鸭蛋。最后热腾腾的炒粿条盛放于碧绿新鲜的修剪芭蕉叶上，高温瞬间激发芭蕉叶天然清香，'镬气'升腾、焦香四溢，是东南亚街头饮食声光气味全感官体验的巅峰范例。",
    "visual_features": {
      "form": "圆形厚底生铁镬置于黑色圆筒炭火炉上；出锅装盘采用垫底的菱形或圆形裁剪新鲜芭蕉叶托底。",
      "color": "深酱油焦糖褐色粿条、鲜红亮橙大虾仁、金黄焦脆鸭蛋碎、翠绿韭菜与乳白豆芽，衬托在深绿生机盎然的芭蕉叶上。",
      "material": "生铁锅、红木木炭/无烟炭块、天然芭蕉叶、陶瓷平盘/红色复古塑料碟、不锈钢翻炒长铁铲。",
      "pattern": "芭蕉叶天然羽状平行叶脉纹路；炒制过程中飞溅的金色火星与翻滚的蒸汽浓烟。",
      "space": "小贩立于宽约1.5米的三轮改装推车或不锈钢立式操作台前，前置透明玻璃食材保温陈列柜，客人围坐于折叠矮塑料桌椅周围。",
      "distinction": "槟城炒粿条区别于新加坡偏甜湿的黑酱油炒法，其特色在于干爽焦香、大量使用鸭蛋提鲜，且必须以生鲜芭蕉叶承托出盘，极具市井乡土感。"
    },
    "visual_keywords": "炭火铁镬|镬气升腾|芭蕉叶垫底|深酱色宽粿条|焦香虾仁|小贩三轮餐车",
