    "region": "霹雳州怡保旧街场",
    "name_cn": "怡保旧街场白咖啡与厚胎绿花瓷杯",
    "name_en": "Ipoh White Coffee & Traditional Floral Kopitiam Cup",
    "name_local": "Ipoh white coffee / 怡保白咖啡",
    "name_local_roman": "—",
    "tradition": "霹雳州锡矿时期海南咖啡师调配手艺、南洋茶餐室咖啡器具美学",
    "summary": "怡保白咖啡诞生于19世纪中叶霹雳州近打谷锡矿鼎盛时期。当年移居怡保的海南籍咖啡师傅针对西方人酸苦浓烈的黑咖啡，改良烘焙配方——仅加入少许植物人造黄油在低温下烘炒咖啡豆，不掺焦糖与麦粒，冲泡出的咖啡苦味极低、温润醇厚，呈浅浅的金褐色，故称'白咖啡'。冲泡后以传统长嘴铝水壶调合炼乳，装入标志性的厚壁白瓷杯（杯外印有深绿色卷草花卉图案或复古红公鸡），杯底极厚，能持久锁温并散发出浓郁南洋怀旧情调。",
    "visual_features": {
      "form": "矮圆筒状厚胎白瓷咖啡杯配平底小茶碟；长嘴细颈铝合金或不锈钢冲咖啡水壶。",
      "color": "暖金褐色的顺滑咖啡液体表面浮有一层轻盈浅杏色油脂泡沫；白瓷杯身饰有墨绿经典植物印花图案。",
      "material": "高岭土重胎日用陶瓷（壁厚达5-7毫米以保温抗摔）、天然橡胶圈封口玻璃咖啡储豆罐、压花不锈钢勺。",
      "pattern": "杯身手印深绿色对开缠枝莨苕叶图案、花苞纹或复古彩绘大公鸡图案，杯口描一圈细金线或纯白口沿。",
      "space": "置于传统圆大理石台面木圆桌（Kopitiam marble table）中央，与烤土司吐司架、半熟水煮蛋小玻璃碗共同构成经典的南洋早餐静物陈设。",
      "distinction": "与现代意式浓缩咖啡杯的轻薄冷淡相比，南洋厚壁绿花杯握感温厚沉稳、釉面光滑微润，具有极强的怀旧手感与市井生活记忆联结。"
    },
    "visual_keywords": "厚壁绿花瓷杯|金褐白咖啡|微脂泡沫|大理石圆桌|海南拉咖啡|复古早餐器物",
