    "name_local_roman": "Kek Lok Si",
    "tradition": "南洋大乘佛教、东南亚汉藏泰三大佛教建筑流派大融合",
    "summary": "槟城极乐寺（Kek Lok Si）始建于1891年，依亚依淡山势梯级而建，是东南亚规模最大的汉传佛教寺庙建筑群之一。寺庙核心视觉地标为1930年竣工的高达30米的'万佛宝塔'（Pagoda of Ten Thousand Buddhas / Ban Po Thar）。该塔建筑构思极其独特：塔基与底层三层采用中国传统汉式八角形飞檐重阁，中段三层采用缅甸与泰国小乘佛教风格的直壁黄琉璃瓦八角塔身，塔顶三层与金顶则完全采用泰国与藏传佛教风格的圆锥金伞刹，完美将大乘佛教、南传上座部与藏传密宗的建筑母题浑然合为一体。",
    "visual_features": {
      "form": "七层八角复合式佛塔，由下至上三种建筑形制递进过渡；山体依势层层递进排列众多殿阁与飞檐连廊。",
      "color": "中国红斗拱柱廊、白粉抹灰外墙、泰式亮黄琉璃瓦面与纯金尖顶塔刹相映生辉。",
      "material": "白大理石雕刻栏杆、花岗岩基座、陶制琉璃瓦当滴水、汉白玉小佛像（塔内供奉万尊铜石浮雕佛像）。",
      "pattern": "汉式龙凤宝珠脊饰、泰式火焰状小塔角饰（Chofah）、藏式仰覆莲瓣纹与吉祥八宝图样。",
      "space": "佛塔耸立于山腰平台之上，拾级登塔可360度远眺乔治市与马六甲海峡海天景观。",
      "distinction": "全球极为罕见的在一座独立佛塔上自下而上严格融合汉式、泰缅式与藏式三种完全不同形制的佛教建筑杰作，是南洋多元文化包容汇流的终极实体象征。"
    },
    "visual_keywords": "汉藏泰合璧万佛塔|八角飞檐中式基底|泰式黄琉璃塔身|金伞塔刹|梯级山寺|万尊佛雕",
    "tags": "宗教建筑|多元融合|景观制高点|历史遗产|建筑细部|主题展览",
