    "region": "曼谷巴吞旺区",
    "name_cn": "曼谷传统中庭高脚柚木屋群（金汤普森泰屋）",
    "name_en": "Traditional Thai Teakwood House (Jim Thompson House)",
    "name_local": "เรือนไทย / Ruen Thai",
    "name_local_roman": "Ruen Thai",
    "tradition": "中部泰国大城府传统木构民居建筑（Ruen Thai）、热带水乡悬挑结构",
    "summary": "泰屋（Ruen Thai）是泰国中部平原传统高脚柚木民居的经典形式。曼谷著名的金汤普森建筑群（Jim Thompson House）汇集了6栋来自大城府与曼谷邦卡皮的百年老柚木建筑拆迁重组而成。整栋建筑完全采用古法榫卯连接，无需一颗铁钉。建筑底层以坚固厚重的柚木圆柱高高架空防洪防潮，上层各居住单体围绕开敞式中央硬木露天平台（Chaan）环抱布置，外墙板呈上收下放的微微内倾斜度以增强抗震抗风稳定性，双坡高耸屋顶端部饰有优雅弯翘的'天鹅尾'（Ngao）挑檐，是热带木建筑通风景观与环境适应性的巅峰之作。",
    "visual_features": {
      "form": "高脚柱网架空底层高约2.5-3米；双坡陡峭大屋顶端部微挑呈优美弧线；外墙板向上微收倾斜约5度；各单体围绕中心大木平台布置。",
      "color": "柚木天然氧化沉淀的古铜棕色、栗壳深红棕色与暗红木油保护层，与庭院热带浓绿植物形成静谧高级对比。",
      "material": "百年老料天然红柚木（Teakwood）、手工红陶瓦/素面扁陶瓦屋面、防腐纯天然生漆与桐油。",
      "pattern": "外墙窗栏的菱形格栅、屋檐悬挑'天鹅尾'（Ngao）优美向上翻挑倒钩、窗楣下方的传统透气木雕齿状纹。",
      "space": "架空底层形成极其凉爽通风的半室外生活与停舟空间；上层中央木平台无顶开敞，成为贯通各房起居与宴饮的私密花园核心。",
      "distinction": "与马来西亚马来高脚屋（Rumah Melayu）横向舒展、百叶窗较多不同，泰式Ruen Thai屋顶坡度更为陡峭尖拔、檐角向上翻翘弧度更大、墙板内收倾角极为明确，雕刻线条更显利落洗练。"
    },
