    "name_local": "ส้มตำ / Som tum",
    "name_local_roman": "Som tum",
    "tradition": "泰国东北部（依善 Isan）传统发酵与舂捣凉拌饮食文化",
    "summary": "青木瓜沙拉（Som Tum）是泰国饮食中最具声音与嗅觉辨识度的国民街头小吃。每个典型摊档前必有一具高深的大号天然原木臼（Krok Mai）或粗红泥陶臼。小贩手持沉重木杵，依次将鲜红朝天椒、紫皮生大蒜、青柠角、椰糖、鱼露与发酵小螃蟹/腌鱼汁（Pla Ra）舂碎融合，随后投入新鲜刨出的如象牙般洁白的爽脆青木瓜细丝、长豆角、樱桃小番茄与油炸花生米，双手一杵一勺有节奏地'嗒、嗒、笃、笃'快速敲击翻拌。那富有乐感的敲击声与扑鼻而来的酸辣鲜咸香气，是泰国大街小巷全天候最鲜活的感官召唤。",
    "visual_features": {
      "form": "倒圆锥形高深木臼（高约35-45厘米）配带弧度长柄硬木杵；小贩手推车前整齐摆放多格亚克力半透明食材分类盒。",
      "color": "青木瓜丝的晶莹象牙白、小番茄的明艳亮红、青柠与长豆角的油绿、鸟眼椒的火红与花生仁的焦黄构成极度开胃的高饱和色盘。",
      "material": "老硬实木整木挖制石臼/粗陶红泥臼、无漆木杵、透明玻璃陈列箱、不锈钢调味汁深桶与折叠木桌。",
      "pattern": "木臼表面天然环状木轮纹与敲击磨损斑痕；青木瓜手刮刀削出的自然长条卷曲丝状纹理。",
      "space": "摊位占地仅约1.2×0.8米，操作核心完全集中于木臼上方30厘米立方空间内，小贩身体与敲击声构成极高密度的街头剧场表演中心。",
      "distinction": "强调'舂捣'（Pounding）而非单纯搅拌，木臼与木杵沉闷而清脆的撞击声是其最独特的声音景观（Soundscape），色彩极尽酸辣鲜亮。"
    },
    "visual_keywords": "高深木臼原木杵|青木瓜丝晶莹白|朝天椒亮红|青柠角绿|敲击声剧场感|透明食材格",
    "tags": "街头小吃|烹饪表演|声音景观|特色摊位|市井烟火|器物陈列",
