    "region": "清迈府桑甘烹县博桑村",
    "name_cn": "清迈博桑手绘彩绘油纸桑皮伞",
    "name_en": "Chiang Mai Bo Sang Handmade Saa Paper Umbrellas",
    "name_local": "ร่มบ่อสร้าง / Rom Bo Sang",
    "name_local_roman": "Rom Bo Sang",
    "tradition": "兰纳泰王国（Lanna）古法手工造纸与彩绘雨伞制作非遗传统",
    "summary": "清迈博桑村（Bo Sang）以历经数百年的手绘雨伞村落闻名于世，相传最早由一位云游缅甸的缅泰僧侣带回造伞手艺。博桑伞全部使用天然构树皮经古法蒸煮、捶打制成的韧性极佳的桑皮纸（Saa paper）或本地纯棉布为伞面，伞骨精选优质刺竹经过防蛀浸泡手工削成细密伞骨架。最具视觉震撼力的是伞面彩绘工序——民间画师纯熟地手持自制画笔，用天然植物与矿物耐水颜料在展开的伞面上即兴挥洒兰纳传统盛开热带花卉、金龙彩凤、孔雀开屏及秀美山林，色彩极度绚丽欢畅。",
    "visual_features": {
      "form": "正圆形伞面，伞骨由数十根竹篾细密放射支撑；多把伞展开倒扣或高低错落悬挂时形成壮观的圆形穹顶伞阵。",
      "color": "鲜艳的明黄、正红、翠绿、蔚蓝底色，表面绘制多色渐变的大朵牡丹花卉、粉白荷花与金绿孔雀羽翎。",
      "material": "构树桑皮纸（Saa Paper）、柔韧竹篾骨架、纯棉线穿扎、天然柿漆/桐油防水涂层。",
      "pattern": "兰纳传统缠枝花卉图案、热带凤鸟孔雀纹、飞檐祥云纹与渐变花瓣笔触。",
      "space": "单伞直径从30厘米至特大号3-4米庭院伞不等；当成百上千把彩伞倒悬于天花板或广场上空时，形成极为绚烂热烈的天幕艺术装置。",
      "distinction": "相比中国江南油纸伞的文人素雅水墨风格，博桑伞色彩极其饱和浓郁热烈，桑皮纸纹理质朴透光，带有强烈的热带森林与兰纳节庆气息。"
    },
