    "name_local_roman": "San Phra Phum",
    "tradition": "泰国万物有灵民间信仰、婆罗门教与佛教融合的护土土地神崇拜",
    "summary": "神屋（San Phra Phum，意为'土地护持神之圣所'）是泰国城乡最具普遍性的街头民间信仰景观。无论是现代高档商场大厦、酒店、路边加油站还是传统民居院落，落成前必须择吉日请高僧或法师在院落最佳方位立一根独立立柱，柱顶架设一座精雕细琢的缩小版泰式金色或彩色微型宫殿神龛。神屋内供奉守护土地的神祇木雕与随从雕像，门前案台上每日换新供奉鲜艳的黄色万寿菊花环、红色芬达汽水（代表甘甜鲜红血食之古礼置换）、清水、香蕉与点燃的线香，体现了人与看不见的空间灵气和谐共处的南洋民俗哲学。",
    "visual_features": {
      "form": "独柱支撑的四方微型泰式传统宫殿阁楼，带有陡峭四坡瓦顶或尖顶佛塔顶刹，前设微型露台步阶。",
      "color": "神屋本体以大红、亮绿、深天蓝配高亮描金；供品以亮黄万寿菊串与鲜红汽水瓶构成极度醒目的红黄撞色组。",
      "material": "模铸彩色水泥釉面预制件/精雕金漆柚木、玻璃微型马赛克剪粘嵌饰、鲜花环、玻璃饮料瓶与黄铜香炉。",
      "pattern": "屋脊边缘装饰微型那伽蛇神（Naga）雕纹、泰式金漆火焰尖角、四面围栏镂空雕饰。",
      "space": "高约1.8-2.2米（与成人视线齐平），通常立于建筑主入口拐角花园或绿植掩映处，成为现代都市水泥森林中精致小巧的灵性庇护所。",
      "distinction": "微型宫殿造型精致写实如同建筑模型，红芬达插吸管与金黄花环的现代祭拜组合是极其独特的当代泰国生活风情。"
    },
    "visual_keywords": "微型泰式宫殿神屋|独柱立式神龛|金漆飞檐Naga蛇纹|万寿菊鲜花环|红芬达供奉|街头日常灵性",
    "tags": "民间信仰|微型建筑|街角景观|祭祀装置|色彩构成|民俗打卡",
