    "country_code": "VN",
    "country": "越南",
    "region": "承天顺化省及全越",
    "name_cn": "越南顺化手工缝制圆锥形棕榈叶斗笠（Nón lá / 诗意斗笠）",
    "name_en": "Vietnamese Conical Palm Leaf Hat (Nón lá)",
    "name_local": "Nón lá / Nón bài thơ",
    "name_local_roman": "Non la",
    "tradition": "越南稻作水乡防雨遮阳传统用具、顺化皇城女性'诗意斗笠'手艺",
    "summary": "斗笠（Nón lá，意为'树叶帽子'）是越南最具代表性的传统服饰与民间手工艺品，其历史可追溯至公元前数个世纪的东山文化铜鼓图案。由老艺人精选幼嫩的野生高山棕榈叶（Lá cọ）经硫磺熏白、手工烫平后，整齐排布于16道由细竹篾弯成的一圈圈同心圆骨架上，使用透明尼龙线或丝线逐针纯手工密密缝制而成。在古都顺化，艺人们更创造出独步天下的'诗意斗笠'（Nón bài thơ）——在双层透光树叶夹层中巧妙夹入剪纸诗词与古皇城竹影剪影，平日不显，在热带烈日逆光映照下，顶上便浮现出一幅婉约空灵的水墨诗画。",
    "visual_features": {
      "form": "极其对称规整的圆锥形（底面直径约40-42厘米，高约20-25厘米），由十六道直径递减的同心圆竹圈支撑构架而成。",
      "color": "刚制成时呈现优雅的米白浅象牙色，常年使用后经阳光油脂浸润转为温润的淡金草黄色；系带多为桃粉、天蓝或鹅黄色真丝缎带。",
      "material": "天然高山棕榈叶或蒲葵叶、削圆细竹篾环、防潮透明丝线、柔软下颌丝绸系带。",
      "pattern": "同心圆竹圈构成的精密螺旋环形肋条肌理；顺化诗笠在阳光透射下隐现的秀丽汉字诗句、宝塔与竹林透光剪影。",
      "space": "单体轻薄如翼仅重几十克；成千上百顶斗笠通过绳索穿系陈列于墙面或悬吊于空中，构成极具韵律感的光影波浪墙面。",
      "distinction": "相比中国江南宽平竹编斗笠或缅甸宽大漆笠，越南Nón lá圆锥高挺拔、十六圈竹骨规整精确，选用白净棕榈叶整张压制，形态极具女性婉约美感与现代雕塑几何极简感。"
    },
