    "id": "VN-12-0001",
    "country_code": "VN",
    "country": "越南",
    "region": "河内市还剑湖畔及红河三角洲",
    "name_cn": "红河三角洲传统水上木偶戏（水偶戏）",
    "name_en": "Red River Delta Traditional Water Puppetry",
    "name_local": "Múa rối nước",
    "name_local_roman": "Mua roi nuoc",
    "tradition": "红河三角洲千百年水稻田淹水季节民间演艺、还剑湖传统水偶剧",
    "summary": "水上木偶戏（Múa rối nước）是越南独一无二、拥有逾千年历史的国宝级传统表演艺术，始于李朝（11世纪）红河三角洲稻农在水淹稻田中的自娱自乐。表演舞台设于齐腰深的浑然水塘中，后台以悬垂的竹帘为屏障，木偶操控大师们浸泡在水中，通过隐匿于水面下数米长的竹竿、长绳与杠杆机关操纵木偶。木偶采用耐水轻质的无花果木手工雕刻，涂上生漆矿物油彩，在水面上腾空翻滚、口喷烟火、破浪划行，伴随岸上传统八音弦乐与民间快板，展现放牛捉鱼、赛龙舟与金龟还剑等古老传说。",
    "visual_features": {
      "form": "舞台为传统三开间红瓦歇山顶水上小亭（Thủy đình），水面即舞台；木偶高约30-50厘米，造型圆润诙谐、身手可活动。",
      "color": "中国红与孔雀绿漆彩、金箔勾勒，水面上倒映着灯光与粼粼波光，偶人出没时喷出白烟与金黄火花。",
      "material": "轻质无花果木（Gỗ sung）、天然防水大漆（Sơn ta）、竹帘屏风、水下隐形长竹杠与拉线机关。",
      "pattern": "木偶面部生动的滑稽神情、戏水金龙鳞片浮雕纹、水中激起的一圈圈涟漪水波纹理。",
      "space": "将沉浸式水域直接化为舞台台面，水体的流动、阻力与溅起的水珠成为表演画面的有机组成部分，极具水乡灵动感。",
      "distinction": "全球独此一家的水面提线机关木偶艺术，舞台下完全是真实水池，不仅消弭了传统戏台的地面刚性边界，水波激荡更让木偶动作具有惊人的生动活力。"
    },
    "visual_keywords": "水面舞台Thủy đình|无花果木雕彩偶|水下长竹竿机关|烟火破水而出|诙谐人物表情|稻作水上文化",
    "tags": "民间艺术|水景演艺|沉浸式互动|非遗戏剧|装置艺术|传统演出",
