    "tradition": "红河下游七百年古陶村、越法与东亚国际海运外销陶艺重镇",
    "summary": "钵场陶瓷村（Bát Tràng）位于河内市郊红河左岸，拥有自14世纪李朝以来的700余年制陶历史。这里蕴藏着极其优质的高岭白泥，工匠世代以此烧造供奉升龙皇城的宫廷瓷器与远销日本、欧洲的精美日用器皿。钵场陶艺最显著的视觉特征为独步东方的'象牙白开片裂纹釉'（Men rạn）与铁青色自由写意青花手绘。陶胎坚致敦厚，釉层肥厚滋润，开片裂纹有如天然碎冰纹理，在岁月氧化中呈现如古玉般的沉静肌理，是安南古陶朴拙自然美学的活态见证。",
    "visual_features": {
      "form": "大号鼓形酒瓮、水缸、高颈花觚、大口茶碗与香炉，胎骨厚重端庄，轮廓饱满微浑带有手工拉胚的天然呼吸感。",
      "color": "米白偏灰的古朴象牙白裂纹底釉，搭配青灰、靛蓝、土褐与铁锈红的自由手绘色调。",
      "material": "红河沉积优质高岭白土、天然草木灰与长石熔融开片釉、柴烧龙窑/倒焰窑烧制。",
      "pattern": "器表密布细碎深邃的'冰裂开片纹'；手绘图案包括粗笔墨卷草莲塘、腾云游龙、四灵神兽及水鸟荷花，笔触潇洒恣意。",
      "space": "陶罐与大缸多密集堆叠于村落老墙脚下或作庭院喷泉水景，厚重粗陶质感能为任何空间注入踏实的古物大地气息。",
      "distinction": "与景德镇青花的极其精密薄胎不同，钵场陶瓷更偏向粗陶器皿的浑厚质朴，开片裂纹深邃立体且手绘笔墨粗犷写意，带有极浓厚的越南水乡乡野天然气韵。"
    },
